    """Find cells in the chamber around special cell (orthogonal neighbors only)"""
    seen = set()
    cells = set()

    # Add orthogonal neighbors
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = sr + dr, sc + dc
        if 0 <= nr < 30 and 0 <= nc < 30 and grid[nr][nc] == 1:
            cells.add((nr, nc))

    # BFS from orthogonal neighbors
    queue = list(cells)
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
